"""Generate the feed fixtures that must not be committed (issue #12, docs/contracts/fixtures.md).

- ``huge_10mb.xml``: a valid RSS 2.0 feed of at least 10 MiB (deterministic items).
- ``entity_expansion.xml``: a "billion laughs" internal-entity expansion. With the defaults
  it would expand to 10**9 copies of a short string (about 3 GB).
- ``deep_nesting.xml``: one item with an extension element nested 100,000 levels deep.

Tests call the functions directly or fetch them from the fixture server (``/feeds/<name>``).
Files written by the CLI go to ``feeds/generated/``, which is git-ignored::

    uv run python -m tests.fixtures.feeds.generate [--out DIR]
"""

from __future__ import annotations

import argparse
from collections.abc import Callable
from pathlib import Path

MIB = 1024 * 1024
GENERATED_DIR = Path(__file__).parent / "generated"

_HEAD = (
    '<?xml version="1.0" encoding="UTF-8"?>\n'
    '<rss version="2.0">\n  <channel>\n'
    "    <title>Huge feed (generated fixture)</title>\n"
    "    <link>https://example.invalid/huge</link>\n"
    "    <description>Generated by tests/fixtures/feeds/generate.py.</description>\n"
)
_TAIL = "  </channel>\n</rss>\n"
_ITEM = (
    "    <item>\n"
    "      <title>Generated cybersecurity notice {n:07d}</title>\n"
    "      <link>https://example.invalid/huge/{n:07d}</link>\n"
    '      <guid isPermaLink="false">huge-{n:07d}</guid>\n'
    "      <pubDate>Mon, 02 Nov 2026 {h:02d}:{m:02d}:00 GMT</pubDate>\n"
    "      <description>{body}</description>\n"
    "    </item>\n"
)
_BODY = (
    "Operators of essential services must notify significant incidents to the competent "
    "authority without undue delay and in any event within 72 hours. " * 4
).strip()


def huge_feed(min_bytes: int = 10 * MIB) -> bytes:
    """A valid RSS document of at least ``min_bytes`` bytes; same output for the same size."""
    parts = [_HEAD]
    size = len(_HEAD) + len(_TAIL)
    n = 0
    while size < min_bytes:
        item = _ITEM.format(n=n, h=n // 60 % 24, m=n % 60, body=_BODY)
        parts.append(item)
        size += len(item)
        n += 1
    parts.append(_TAIL)
    return "".join(parts).encode("utf-8")


def entity_expansion(levels: int = 9, fan_out: int = 10) -> bytes:
    """Nested internal entities: ``fan_out ** levels`` copies of 'lol' if expanded."""
    lines = ['<!ENTITY lol0 "lol">']
    for i in range(1, levels + 1):
        refs = f"&lol{i - 1};" * fan_out
        lines.append(f'<!ENTITY lol{i} "{refs}">')
    dtd = "\n  ".join(lines)
    doc = (
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        f"<!DOCTYPE rss [\n  {dtd}\n]>\n"
        '<rss version="2.0"><channel><title>Entity expansion (generated fixture)</title>'
        "<link>https://example.invalid/</link><description>billion laughs</description>"
        f"<item><title>&lol{levels};</title><guid>entity-1</guid></item>"
        "</channel></rss>\n"
    )
    return doc.encode("utf-8")


def deep_nesting(depth: int = 100_000) -> bytes:
    """One item whose extension element is nested ``depth`` levels deep."""
    doc = (
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<rss version="2.0" xmlns:rw="https://regwatch.invalid/ns/fixture"><channel>'
        "<title>Deep nesting (generated fixture)</title><link>https://example.invalid/</link>"
        "<description>deep</description><item><title>Deep</title><guid>deep-1</guid>"
        + "<rw:x>" * depth
        + "deep"
        + "</rw:x>" * depth
        + "</item></channel></rss>\n"
    )
    return doc.encode("utf-8")


GENERATORS: dict[str, Callable[[], bytes]] = {
    "huge_10mb.xml": huge_feed,
    "entity_expansion.xml": entity_expansion,
    "deep_nesting.xml": deep_nesting,
}


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Write generated feed fixtures")
    parser.add_argument("--out", type=Path, default=GENERATED_DIR)
    args = parser.parse_args(argv)
    args.out.mkdir(parents=True, exist_ok=True)
    for name, fn in GENERATORS.items():
        data = fn()
        (args.out / name).write_bytes(data)
        print(f"{args.out / name}: {len(data):,} bytes")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
